import test from 'node:test';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {workbenchPlanningFixture} from '../tests/fixtures/workbench-planning.mjs';
import {inputFixture} from '../tests/fixtures/input-data.mjs';
const {chromium,expect:baseExpect}=createRequire(new URL('../templates/web-crud-v1/package.json',import.meta.url))('@playwright/test');
const expect=baseExpect.configure({timeout:35000});
const label='我已审阅当前计划、需求依据与沿用结果，明确同意按此计划实施。';
async function browser(t,headers){const b=await chromium.launch({channel:process.env.PLAYWRIGHT_CHROMIUM_CHANNEL??'msedge',headless:true});t.after(()=>b.close());return b.newContext({extraHTTPHeaders:headers});}
async function commands(page){return page.evaluate(()=>new Promise((resolve,reject)=>{const r=indexedDB.open('devmesh.workbench',1);r.onsuccess=()=>{const db=r.result,tx=db.transaction('commands'),q=tx.objectStore('commands').getAll();tx.oncomplete=()=>{db.close();resolve(q.result);};tx.onabort=()=>reject(tx.error);};r.onerror=()=>reject(r.error);}));}
test('reproduction: original plan confirmation remains reachable when the plan read is unavailable',{timeout:240000},async t=>{
 const f=await workbenchPlanningFixture(t),context=await browser(t,{authorization:'Bearer user_1'}),page=await context.newPage();await page.goto(f.base+'/api/v1/workbench/view?projectId='+f.projectId+'&runId='+f.runId);await expect(page.getByLabel(label)).toBeEnabled();await page.route('**/api/v1/runs/*/plans/1:confirm',route=>route.abort('failed'),{times:1});await page.getByLabel(label).check();await page.getByRole('button',{name:'明确确认计划',exact:true}).click();await expect(page.getByRole('button',{name:'核实原计划确认',exact:true})).toBeVisible();const original=(await commands(page))[0];assert.equal(original.receipt,null);assert.equal(f.sql('SELECT count(*) n FROM plan_confirmations')[0].n,0);
 await page.route('**/api/v1/runs/*/plans?*',route=>route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{code:'TEST_PLAN_UNAVAILABLE'}})}));await page.reload();await expect(page.getByRole('alert').filter({hasText:'理解或计划依据暂不可读'})).toBeVisible();assert.deepEqual((await commands(page))[0].envelope,original.envelope);t.diagnostic('Existing exact pending command retained; controlled plan GET failure, zero confirmation business writes.');await expect(page.getByRole('button',{name:'核实原计划确认',exact:true})).toBeVisible();
});
test('reproduction: current terminal Run exposes its pending original message without admitting new input',{timeout:180000},async t=>{
 const f=await inputFixture(t,{identityResolver:()=>({principalId:'user_1'})}),p=(await f.create({name:'终态原消息恢复'})).body.result,context=await browser(t,{}),page=await context.newPage();await page.goto(f.origin+'/api/v1/workbench/view?projectId='+p.projectId+'&runId='+p.runId);const input=page.getByLabel('输入正文',{exact:true});await expect(input).toBeEnabled();await input.fill('保留终态前的原请求');await expect(page.getByRole('status').filter({hasText:'草稿已保存在本机'})).toBeVisible();await page.route('**/api/v1/runs/*/messages',route=>route.abort('failed'),{times:1});await page.getByRole('button',{name:'提交输入',exact:true}).click();await expect(page.getByRole('alert')).toBeVisible();const original=(await commands(page))[0];assert.equal(original.receipt,null);
 // Fixture only: seed a terminal Run; this does not exercise or claim CancelRun.
 f.sql("UPDATE runs SET terminal_outcome='CANCELLED',ended_at=?,resource_revision=resource_revision+1 WHERE run_id=?",new Date().toISOString(),p.runId);await page.reload();await expect(page.getByText('当前权限或执行状态不允许提交输入。',{exact:true})).toBeVisible();assert.deepEqual((await commands(page))[0].envelope,original.envelope);assert.equal(f.sql('SELECT count(*) n FROM input_messages')[0].n,1);t.diagnostic('Explicit seeded terminal state; actual authorized workspace and native stored original; no new message.');await expect(page.getByRole('button',{name:'核实原提交',exact:true})).toBeVisible();
});
